BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=public,extensions;
SELECT no_plan();
SELECT is(public.api_schema_ready(),true,'Reflection catalog is ready');
ALTER TABLE public.reflections DISABLE ROW LEVEL SECURITY;
SELECT is(public.api_schema_ready(),false,'Missing reflection RLS fails readiness');
ALTER TABLE public.reflections ENABLE ROW LEVEL SECURITY;
SELECT is(has_table_privilege('authenticated','private.reflection_jobs','SELECT'),false,'Clients cannot see orchestration metadata');
SELECT is(has_function_privilege('authenticated','public.reflection_claim(integer)','EXECUTE'),false,'Users cannot claim workers');
SELECT is(has_column_privilege('authenticated','public.reflections','context_ids','SELECT'),false,'Context provenance IDs are private');
SELECT is(private.next_morning('2026-03-07T22:00:00Z','America/New_York','07:30'),'2026-03-08T11:30:00Z'::timestamptz,'Spring DST uses next local calendar morning');
SELECT is(private.next_morning('2026-10-31T22:00:00Z','America/New_York','07:30'),'2026-11-01T12:30:00Z'::timestamptz,'Fall DST adjusts UTC rather than adding 24 hours');
SELECT is(private.next_morning('2026-10-12T18:00:00Z','Asia/Hong_Kong','07:00'),'2026-10-13T23:00:00Z'::timestamptz,'Writing after local midnight schedules the following local day');
SELECT is(private.next_morning('2026-10-12T18:00:00Z','Asia/Kathmandu','07:30'),'2026-10-13T01:45:00Z'::timestamptz,'Fractional offsets are preserved');
SELECT is(private.next_morning('2011-12-29T18:00:00Z','Pacific/Apia','07:30'),'2011-12-30T17:30:00Z'::timestamptz,'Skipped civil day shifts forward');
SELECT throws_ok($$SELECT private.next_morning(now(),'Bad/Zone','07:30')$$,'P0001','bad_request','Unknown zone is rejected');
INSERT INTO auth.users(id,aud,role,email) VALUES
('aaaaaaaa-1212-4121-8121-aaaaaaaaaaaa','authenticated','authenticated','reflection-one@example.invalid'),
('bbbbbbbb-1212-4121-8121-bbbbbbbbbbbb','authenticated','authenticated','reflection-two@example.invalid');
INSERT INTO auth.sessions(id,user_id) SELECT id,id FROM auth.users WHERE id IN ('aaaaaaaa-1212-4121-8121-aaaaaaaaaaaa','bbbbbbbb-1212-4121-8121-bbbbbbbbbbbb');
CREATE TEMP TABLE reflection_results(label text PRIMARY KEY,payload jsonb);
GRANT SELECT,INSERT,UPDATE ON reflection_results TO authenticated,service_role;
SELECT set_config('request.jwt.claim.sub','',true);
SELECT set_config('request.jwt.claims',jsonb_build_object('sub','aaaaaaaa-1212-4121-8121-aaaaaaaaaaaa','session_id','aaaaaaaa-1212-4121-8121-aaaaaaaaaaaa','amr',jsonb_build_array(jsonb_build_object('method','password','timestamp',floor(extract(epoch FROM statement_timestamp())))))::text,true);
SET LOCAL ROLE authenticated;
INSERT INTO reflection_results VALUES('entry',public.entry_create('Fictional reflection entry',gen_random_uuid(),false)->'entry');
INSERT INTO reflection_results VALUES('memory',public.memory_create('Fictional approved context',NULL,true,gen_random_uuid()));
INSERT INTO reflection_results VALUES('job',public.reflection_request((SELECT (payload->>'id')::uuid FROM reflection_results WHERE label='entry'),1));
SELECT is((SELECT payload->>'status' FROM reflection_results WHERE label='job'),'pending','Explicit consent creates a pending job');
SELECT is(public.reflection_request((SELECT (payload->>'id')::uuid FROM reflection_results WHERE label='entry'),1),(SELECT payload FROM reflection_results WHERE label='job'),'Repeat consent returns the existing job');
SELECT throws_ok($$SELECT public.reflection_request((SELECT (payload->>'id')::uuid FROM reflection_results WHERE label='entry'),2)$$,'P0001','conflict','Stale consent revision is rejected');
SELECT throws_ok($$SELECT public.reflection_claim(1)$$,'42501',NULL,'Client cannot claim a job');
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT is(public.reflection_claim(5),'[]'::jsonb,'Future jobs are not delivered immediately');
RESET ROLE;
UPDATE private.reflection_jobs SET due_at=clock_timestamp()-interval '1 second',next_attempt_at=clock_timestamp()-interval '1 second';
SET LOCAL ROLE service_role;
INSERT INTO reflection_results VALUES('claim',public.reflection_claim(5)->0);
SELECT is(public.reflection_claim(5),'[]'::jsonb,'A live lease cannot be claimed twice');
SELECT throws_ok($$SELECT public.reflection_input((SELECT (payload->>'id')::uuid FROM reflection_results WHERE label='claim'),gen_random_uuid())$$,'P0001','conflict','Wrong lease cannot read content');
INSERT INTO reflection_results VALUES('input',public.reflection_input((SELECT (payload->>'id')::uuid FROM reflection_results WHERE label='claim'),(SELECT (payload->>'lease_token')::uuid FROM reflection_results WHERE label='claim')));
SELECT is((SELECT payload->'entry'->>'text' FROM reflection_results WHERE label='input'),'Fictional reflection entry','Worker receives current consented revision');
SELECT is((SELECT jsonb_array_length(payload->'memories') FROM reflection_results WHERE label='input'),1,'Worker receives only approved context');
INSERT INTO reflection_results VALUES('output',jsonb_build_object('version',1,'request_id',(SELECT payload->>'id' FROM reflection_results WHERE label='job'),'entry_revision',1,'letter',jsonb_build_object('greet','Hello','said','Fictional summary','rec','','step','A small step','sign',''),'actions',jsonb_build_array(jsonb_build_object('id','cccccccc-1212-4121-8121-cccccccccccc','title','Fictional chosen step')),'provenance',jsonb_build_object('model','fixture','prompt_version','v1')));
SELECT is(public.reflection_finish((SELECT (payload->>'id')::uuid FROM reflection_results WHERE label='claim'),(SELECT (payload->>'lease_token')::uuid FROM reflection_results WHERE label='claim'),(SELECT payload FROM reflection_results WHERE label='output'),ARRAY[(SELECT (payload->>'id')::uuid FROM reflection_results WHERE label='memory')]),true,'Valid fenced output commits exactly once');
SELECT throws_ok($$SELECT public.reflection_finish((SELECT (payload->>'id')::uuid FROM reflection_results WHERE label='claim'),(SELECT (payload->>'lease_token')::uuid FROM reflection_results WHERE label='claim'),(SELECT payload FROM reflection_results WHERE label='output'),ARRAY[]::uuid[])$$,'P0001','conflict','Completion replay cannot produce another letter');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT is(jsonb_array_length(public.reflection_list(20,NULL,NULL)),1,'Owner can read a stored letter');
SELECT is((public.account_export_page('reflections',20,NULL,NULL)->'items'->0->'provenance'->>'model'),'fixture','Recent-sign-in export includes letters');
INSERT INTO reflection_results VALUES('accepted',public.reflection_decide((SELECT (payload->>'id')::uuid FROM reflection_results WHERE label='job'),'cccccccc-1212-4121-8121-cccccccccccc','accepted'));
SELECT is(public.reflection_decide((SELECT (payload->>'id')::uuid FROM reflection_results WHERE label='job'),'cccccccc-1212-4121-8121-cccccccccccc','accepted'),(SELECT payload FROM reflection_results WHERE label='accepted'),'Repeated accept returns the same current todo');
SELECT throws_ok($$SELECT public.reflection_decide((SELECT (payload->>'id')::uuid FROM reflection_results WHERE label='job'),'cccccccc-1212-4121-8121-cccccccccccc','rejected')$$,'P0001','conflict','Opposite decision cannot silently replace acceptance');
SELECT lives_ok($$SELECT public.reflection_correct((SELECT (payload->>'id')::uuid FROM reflection_results WHERE label='job'),'Fictional correction',2)$$,'Owner can explicitly correct a reflection');
SELECT throws_ok($$SELECT public.reflection_correct((SELECT (payload->>'id')::uuid FROM reflection_results WHERE label='job'),'Stale correction',2)$$,'P0001','conflict','Correction respects revisions');
SELECT lives_ok($$SELECT public.product_delete('todos',(SELECT (payload->'todo'->>'id')::uuid FROM reflection_results WHERE label='accepted'))$$,'User can delete an accepted task');
SELECT throws_ok($$SELECT public.reflection_decide((SELECT (payload->>'id')::uuid FROM reflection_results WHERE label='job'),'cccccccc-1212-4121-8121-cccccccccccc','accepted')$$,'P0001','conflict','Accept replay does not resurrect an explicitly deleted task');
SELECT set_config('request.jwt.claims','{"sub":"bbbbbbbb-1212-4121-8121-bbbbbbbbbbbb","session_id":"bbbbbbbb-1212-4121-8121-bbbbbbbbbbbb"}',true);
SELECT is(jsonb_array_length(public.reflection_list(20,NULL,NULL)),0,'Another owner has no letters');
SELECT is((SELECT count(*) FROM public.reflections),0::bigint,'Direct table RLS isolates letters');
SELECT throws_ok($$SELECT public.reflection_get((SELECT (payload->>'id')::uuid FROM reflection_results WHERE label='job'))$$,'P0001','not_found','Another owner cannot read a reflection');
SELECT set_config('request.jwt.claims','{"sub":"aaaaaaaa-1212-4121-8121-aaaaaaaaaaaa","session_id":"aaaaaaaa-1212-4121-8121-aaaaaaaaaaaa"}',true);
SELECT lives_ok($$SELECT public.memory_update((SELECT (payload->>'id')::uuid FROM reflection_results WHERE label='memory'),'Corrected approved memory',true,1)$$,'Memory correction is allowed');
SELECT is(jsonb_array_length(public.reflection_list(20,NULL,NULL)),0,'Changing approved context removes derived letters');
SELECT lives_ok($$SELECT public.reflection_cancel((SELECT (payload->>'id')::uuid FROM reflection_results WHERE label='entry'))$$,'Consent can be cancelled after completion');
INSERT INTO reflection_results VALUES('newjob',public.reflection_request((SELECT (payload->>'id')::uuid FROM reflection_results WHERE label='entry'),1));
RESET ROLE;
UPDATE private.reflection_jobs SET next_attempt_at=clock_timestamp()-interval '1 second';
SET LOCAL ROLE service_role;
UPDATE reflection_results SET payload=public.reflection_claim(1)->0 WHERE label='claim';
SELECT is(public.reflection_retry((SELECT (payload->>'id')::uuid FROM reflection_results WHERE label='claim'),(SELECT (payload->>'lease_token')::uuid FROM reflection_results WHERE label='claim')),true,'A failed service response schedules durable backoff');
SELECT is(public.reflection_claim(1),'[]'::jsonb,'Backoff prevents immediate hot retry');
RESET ROLE;
UPDATE private.reflection_jobs SET next_attempt_at=clock_timestamp()-interval '1 second',lease_token=gen_random_uuid(),lease_until=clock_timestamp()-interval '1 second';
SET LOCAL ROLE service_role;
UPDATE reflection_results SET payload=public.reflection_claim(1)->0 WHERE label='claim';
SELECT ok((SELECT payload->>'lease_token' IS NOT NULL FROM reflection_results WHERE label='claim'),'Expired leases can recover after a worker interruption');
RESET ROLE;
UPDATE private.reflection_jobs SET attempts=5,lease_until=clock_timestamp()-interval '1 second';
SET LOCAL ROLE service_role;
SELECT is(public.reflection_claim(1),'[]'::jsonb,'Retry ceiling prevents indefinite processing');
RESET ROLE;
SELECT is((SELECT status FROM private.reflection_jobs),'failed','Exhausted work is terminal');
SET LOCAL ROLE authenticated;
SELECT lives_ok($$SELECT public.entry_update((SELECT (payload->>'id')::uuid FROM reflection_results WHERE label='entry'),'Edited source',1)$$,'Entry can be edited independently of AI');
RESET ROLE;
SELECT is((SELECT count(*) FROM private.reflection_jobs),0::bigint,'Editing source removes obsolete jobs');
-- Pause includes every historical context source, including explicit corrections.
SET LOCAL ROLE authenticated;
SELECT lives_ok($$SELECT public.settings_update('{"memory_paused":true}',1)$$,'Pausing history works through the settings trigger');
INSERT INTO reflection_results VALUES('contextless',public.reflection_request((SELECT (payload->>'id')::uuid FROM reflection_results WHERE label='entry'),2));
RESET ROLE;
UPDATE private.reflection_jobs SET next_attempt_at=clock_timestamp()-interval '1 second' WHERE status='pending';
SET LOCAL ROLE service_role;
UPDATE reflection_results SET payload=public.reflection_claim(1)->0 WHERE label='claim';
SELECT is(jsonb_array_length(public.reflection_input((SELECT (payload->>'id')::uuid FROM reflection_results WHERE label='claim'),(SELECT (payload->>'lease_token')::uuid FROM reflection_results WHERE label='claim'))->'memories'),0,'Paused input excludes approved memories');
SELECT lives_ok($$SELECT public.reflection_finish((SELECT (payload->>'id')::uuid FROM reflection_results WHERE label='claim'),(SELECT (payload->>'lease_token')::uuid FROM reflection_results WHERE label='claim'),(SELECT payload FROM reflection_results WHERE label='output')||jsonb_build_object('request_id',(SELECT payload->>'id' FROM reflection_results WHERE label='contextless'),'entry_revision',2),ARRAY[]::uuid[])$$,'A context-free fixture can commit');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT lives_ok($$SELECT public.reflection_correct((SELECT (payload->>'id')::uuid FROM reflection_results WHERE label='contextless'),'Fictional prior correction',1)$$,'An explicit correction is retained as owned context');
SELECT lives_ok($$SELECT public.settings_update('{"memory_paused":false}',2)$$,'History can be enabled again');
INSERT INTO reflection_results VALUES('nextentry',public.entry_create('Fictional next entry',gen_random_uuid(),false)->'entry');
INSERT INTO reflection_results VALUES('nextjob',public.reflection_request((SELECT (payload->>'id')::uuid FROM reflection_results WHERE label='nextentry'),1));
RESET ROLE;
UPDATE private.reflection_jobs SET next_attempt_at=clock_timestamp()-interval '1 second' WHERE status='pending';
SET LOCAL ROLE service_role;
UPDATE reflection_results SET payload=public.reflection_claim(1)->0 WHERE label='claim';
SELECT is(jsonb_array_length(public.reflection_input((SELECT (payload->>'id')::uuid FROM reflection_results WHERE label='claim'),(SELECT (payload->>'lease_token')::uuid FROM reflection_results WHERE label='claim'))->'corrections'),1,'Enabled history includes an owned explicit correction');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT lives_ok($$SELECT public.settings_update('{"memory_paused":true}',3)$$,'Pausing again revokes in-flight historical context');
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT throws_ok($$SELECT public.reflection_input((SELECT (payload->>'id')::uuid FROM reflection_results WHERE label='claim'),(SELECT (payload->>'lease_token')::uuid FROM reflection_results WHERE label='claim'))$$,'P0001','conflict','Old context lease is cancelled by pause');
RESET ROLE;
SET LOCAL ROLE authenticated;
INSERT INTO reflection_results VALUES('pausednext',public.reflection_request((SELECT (payload->>'id')::uuid FROM reflection_results WHERE label='nextentry'),1));
RESET ROLE;
UPDATE private.reflection_jobs SET next_attempt_at=clock_timestamp()-interval '1 second' WHERE status='pending';
SET LOCAL ROLE service_role;
UPDATE reflection_results SET payload=public.reflection_claim(1)->0 WHERE label='claim';
SELECT is(jsonb_array_length(public.reflection_input((SELECT (payload->>'id')::uuid FROM reflection_results WHERE label='claim'),(SELECT (payload->>'lease_token')::uuid FROM reflection_results WHERE label='claim'))->'corrections'),0,'Paused history also excludes prior corrections');
RESET ROLE;
SELECT is(public.api_schema_ready(),true,'Catalog remains ready');
SELECT * FROM finish();
ROLLBACK;
